(* [comment removed for export] *)
Definition walk_inv (hs : list Z) (h s : Z) : Prop :=
  exists k, 0 <= k <= Z.of_nat (length hs) /\ s = tab_of (firstn (Z.to_nat k) hs) (bkt h)
    /\ forall i, k < i <= Z.of_nat (length hs) -> hash_of hs i <> h.

