  disjoint_from W d_tab (d_nuniq + 4 - d_tab) -> disjoint_from W d_map1 8 -> disjoint_from W DNB (2 ^ 20) ->
  disjoint_from W s_total 8 -> disjoint_from W s_data0 (s_stored0 + 4 - s_data0) -> disjoint_from W SSB (2 ^ 23) ->
