Ltac dIfF_s := lazymatch goal with |- evt _ _ (MS _ _ (if ?c then _ else _) _ _ _ _) =>
  replace c with false; [cbv iota| symmetry; unfold_cond; rewrite ?dep_signed_lit by lia; rewrite ?unsigned_lit by lia;
                                   solve_cond_rec] end.

